  testNinesixtyCastling(): void {
    let fen = "3r1k1r/4pp2/8/8/8/8/8/4RKR1 w Gd - 1 1"
    let board = new chess.Board(fen, { chess960: true })

    // Let white do the kingside swap.
    let move = board.parseSan("O-O")
    this.assertEqualUsing(board.san(move), "O-O", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(board.xboard(move), "O-O", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(move.fromSquare, chess.F1, (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(move.toSquare, chess.G1, (__actual, __expected) => __actual === __expected)
    this.assertContainsUsing(move, board.legalMoves, (__container, __member) => __container.contains(__member))
    board.push(move)
    this.assertEqualUsing(board.shredderFen(), "3r1k1r/4pp2/8/8/8/8/8/4RRK1 b d - 2 1", (__actual, __expected) => __actual === __expected)

    // Black can not castle kingside.
    this.assertNotContainsUsing(chess.Move.fromUci("e8h8"), board.legalMoves, (__container, __member) => __container.contains(__member))

    // Let black castle queenside.
    move = board.parseSan("O-O-O")
    this.assertEqualUsing(board.san(move), "O-O-O", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(board.xboard(move), "O-O-O", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(move.fromSquare, chess.F8, (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(move.toSquare, chess.D8, (__actual, __expected) => __actual === __expected)
    this.assertContainsUsing(move, board.legalMoves, (__container, __member) => __container.contains(__member))
    board.push(move)
    this.assertEqualUsing(board.shredderFen(), "2kr3r/4pp2/8/8/8/8/8/4RRK1 w - - 3 2", (__actual, __expected) => __actual === __expected)

    // Restore initial position.
    board.pop()
    board.pop()
    this.assertEqualUsing(board.shredderFen(), fen, (__actual, __expected) => __actual === __expected)

    fen = "Qr4k1/4pppp/8/8/8/8/8/R5KR w Hb - 0 1"
    board = new chess.Board(fen, { chess960: true })

    // White can just hop the rook over.
    move = board.parseSan("O-O")
    this.assertEqualUsing(board.san(move), "O-O", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(move.fromSquare, chess.G1, (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(move.toSquare, chess.H1, (__actual, __expected) => __actual === __expected)
    this.assertContainsUsing(move, board.legalMoves, (__container, __member) => __container.contains(__member))
    board.push(move)
    this.assertEqualUsing(board.shredderFen(), "Qr4k1/4pppp/8/8/8/8/8/R4RK1 b b - 1 1", (__actual, __expected) => __actual === __expected)

    // Black can not castle queenside nor kingside.
    this.assertFalse((() => { for (const __item of board.generateCastlingMoves()) { if (__item.bool()) return true; } return false; })())

    // Restore initial position.
    board.pop()
    this.assertEqualUsing(board.shredderFen(), fen, (__actual, __expected) => __actual === __expected)
  }

