  testScholarsMate(): void {
    const board = new chess.Board()

    const e4 = chess.Move.fromUci("e2e4")
    this.assertContainsUsing(e4, board.legalMoves, (__container, __member) => __container.contains(__member))
    board.push(e4)

    const e5 = chess.Move.fromUci("e7e5")
    this.assertContainsUsing(e5, board.legalMoves, (__container, __member) => __container.contains(__member))
    board.push(e5)

    const Qf3 = chess.Move.fromUci("d1f3")
    this.assertContainsUsing(Qf3, board.legalMoves, (__container, __member) => __container.contains(__member))
    board.push(Qf3)

    const Nc6 = chess.Move.fromUci("b8c6")
    this.assertContainsUsing(Nc6, board.legalMoves, (__container, __member) => __container.contains(__member))
    board.push(Nc6)

    const Bc4 = chess.Move.fromUci("f1c4")
    this.assertContainsUsing(Bc4, board.legalMoves, (__container, __member) => __container.contains(__member))
    board.push(Bc4)

    const Rb8 = chess.Move.fromUci("a8b8")
    this.assertContainsUsing(Rb8, board.legalMoves, (__container, __member) => __container.contains(__member))
    board.push(Rb8)

    this.assertFalse(board.isCheck())
    this.assertFalse(board.isCheckmate())
    this.assertFalse(board.isGameOver())
    this.assertFalse(board.isStalemate())

    const Qf7Mate = chess.Move.fromUci("f3f7")
    this.assertContainsUsing(Qf7Mate, board.legalMoves, (__container, __member) => __container.contains(__member))
    board.push(Qf7Mate)

    this.assertTrue(board.isCheck())
    this.assertTrue(board.isCheckmate())
    this.assertTrue(board.isGameOver())
    this.assertTrue(board.isGameOver({ claimDraw: true }))
    this.assertFalse(board.isStalemate())

    this.assertEqualUsing(board.fen(), "1rbqkbnr/pppp1Qpp/2n5/4p3/2B1P3/8/PPPP1PPP/RNB1K1NR b KQk - 0 4", (__actual, __expected) => __actual === __expected)
  }

  testResult(): void {
    // Undetermined.
    let board = new chess.Board()
    this.assertEqualUsing(board.result({ claimDraw: true }), "*", (__actual, __expected) => __actual === __expected)

    // White checkmated.
    board = new chess.Board("rnb1kbnr/pppp1ppp/8/4p3/6Pq/5P2/PPPPP2P/RNBQKBNR w KQkq - 1 3")
    this.assertEqualUsing(board.result({ claimDraw: true }), "0-1", (__actual, __expected) => __actual === __expected)

    // Stalemate.
    board = new chess.Board("7K/7P/7k/8/6q1/8/8/8 w - - 0 1")
    this.assertEqualUsing(board.result(), "1/2-1/2", (__actual, __expected) => __actual === __expected)

    // Insufficient material.
    board = new chess.Board("4k3/8/8/8/8/5B2/8/4K3 w - - 0 1")
    this.assertEqualUsing(board.result(), "1/2-1/2", (__actual, __expected) => __actual === __expected)

    // Fiftyseven-move rule.
    board = new chess.Board("4k3/8/6r1/8/8/8/2R5/4K3 w - - 369 1")
    this.assertEqualUsing(board.result(), "1/2-1/2", (__actual, __expected) => __actual === __expected)

    // Fifty-move rule.
    board = new chess.Board("4k3/8/6r1/8/8/8/2R5/4K3 w - - 120 1")
    this.assertEqualUsing(board.result(), "*", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(board.result({ claimDraw: true }), "1/2-1/2", (__actual, __expected) => __actual === __expected)
  }

  testSan(): void {
    // Castling with check.
    let fen = "rnbk1b1r/ppp2pp1/5n1p/4p1B1/2P5/2N5/PP2PPPP/R3KBNR w KQ - 0 7"
    let board = new chess.Board(fen)
    const longCastleCheck = chess.Move.fromUci("e1a1")
    this.assertEqualUsing(board.san(longCastleCheck), "O-O-O+", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(board.fen(), fen, (__actual, __expected) => __actual === __expected)

    // En passant mate.
    fen = "6bk/7b/8/3pP3/8/8/8/Q3K3 w - d6 0 2"
    board = new chess.Board(fen)
    const fxe6MateEp = chess.Move.fromUci("e5d6")
    this.assertEqualUsing(board.san(fxe6MateEp), "exd6#", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(board.fen(), fen, (__actual, __expected) => __actual === __expected)

    // Test disambiguation.
    fen = "N3k2N/8/8/3N4/N4N1N/2R5/1R6/4K3 w - - 0 1"
    board = new chess.Board(fen)
    this.assertEqualUsing(board.san(chess.Move.fromUci("e1f1")), "Kf1", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(board.san(chess.Move.fromUci("c3c2")), "Rcc2", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(board.san(chess.Move.fromUci("b2c2")), "Rbc2", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(board.san(chess.Move.fromUci("a4b6")), "N4b6", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(board.san(chess.Move.fromUci("h8g6")), "N8g6", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(board.san(chess.Move.fromUci("h4g6")), "Nh4g6", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(board.fen(), fen, (__actual, __expected) => __actual === __expected)

    // Test a bug where shakmaty used overly specific disambiguation.
    fen = "8/2KN1p2/5p2/3N1B1k/5PNp/7P/7P/8 w - -"
    board = new chess.Board(fen)
    this.assertEqualUsing(board.san(chess.Move.fromUci("d5f6")), "N5xf6#", (__actual, __expected) => __actual === __expected)

    // Do not disambiguate illegal alternatives.
    fen = "8/8/8/R2nkn2/8/8/2K5/8 b - - 0 1"
    board = new chess.Board(fen)
    this.assertEqualUsing(board.san(chess.Move.fromUci("f5e3")), "Ne3+", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(board.fen(), fen, (__actual, __expected) => __actual === __expected)

    // Promotion.
    fen = "7k/1p2Npbp/8/2P5/1P1r4/3b2QP/3q1pPK/2RB4 b - - 1 29"
    board = new chess.Board(fen)
    this.assertEqualUsing(board.san(chess.Move.fromUci("f2f1q")), "f1=Q", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(board.san(chess.Move.fromUci("f2f1n")), "f1=N+", (__actual, __expected) => __actual === __expected)
    this.assertEqualUsing(board.fen(), fen, (__actual, __expected) => __actual === __expected)
  }

